def frases(n):
    d=PARTS[n];F=[('hook',"Club de Nuit:"),('h2',"la serie que hizo famosa a Armaf."),('h4',d['h4'])]
    for i,p in enumerate(d['P'],1):
        F+=[('p%d'%i,p[1]),('e%d'%i,p[0]),('n%d'%i,p[2]),('q%d'%i,p[3]),('i%d'%i,p[4])]
    return F+OUTRO
def texto(n):
    d=PARTS[n];t=INTRO_TXT+" "+d['h4']+"\n\n"
    for p in d['P']: t+=" ".join([p[1],p[0],p[2],p[3],p[4]])+"\n\n"
    t+=OUTRO[0][1]+"\n\n"+OUTRO[1][1]+"\n\n"+OUTRO[2][1]
    return t
def cfg(n):
    import json
    d=PARTS[n];P=d['P'];K=['p%d'%i for i in range(1,len(P)+1)]
    J=lambda idx,f=lambda x:x:json.dumps({k:f(p[idx]) for k,p in zip(K,P)},ensure_ascii=False)
    q=lambda s:'“'+s[0].upper()+s[1:].rstrip('.:')+'.”'
    return ("var WORD="+J(5)+";\nvar QT="+J(3,q)+";\nvar MK="+J(6)+";\nvar EMO="+J(0)+";\nvar PAL="+J(7)+";\nvar INTRO="+json.dumps({'n':d['n'],'t':d['t']},ensure_ascii=False)+";\n")
if __name__=='__main__':
    import sys
    for n in (1,2,3,4): print(n,len(texto(n)),'chars')
